head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > getDataListInfo]<br/>GridView 컴포넌트에 바인딩된 DataList 모듈의 정보를 객체로 반환합니다.",
    "validation" : [
        "GridView 컴포넌트에 바인딩된 DataList 모듈의 정보를 객체로 반환해야 합니다.",
        "DataList 가 바인딩되지 않은 경우 undefined 값을 반환해야 합니다.",
        "반환 객체의 id 속성은 GridView 컴포넌트에 바인딩된 DataList 모듈의 디자인 ID 값을 가져야 합니다.",
        "LinkedDataList 모듈이 바인딩된 경우 LinkedDataList 의 디자인 ID 를 반환해야 합니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
// dlt_bind(DataList) 를 바인딩한 GridView 동적 생성.
//  - getDataListInfo() 는 바인딩된 DataList 정보 객체({ id : 디자인 ID }) 를 반환
//  - 반환 객체의 id 는 디자인 ID(예: "dlt_bind") 이므로 mf_ prefix 가 붙지 않는 정적 값으로 비교 검증
scwin.comp_init = async function () {
    // 기존 target/dataList 정리
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    if (typeof target2 !== 'undefined') {
        target2.remove();
    }

    if (typeof target3 !== 'undefined') {
        target3.remove();
    }

    if (typeof lnk_bind !== 'undefined') {
        $p.data.remove("lnk_bind");
    }

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] target1 은 dlt_bind DataList 를 바인딩한 GridView, target2 는 DataList 미바인딩 GridView, target3 은 lnk_bind LinkedDataList 를 바인딩한 GridView 로 생성됩니다.\n[확인] (정보 확인) target1.getDataListInfo() 가 정보 객체를 반환하고 id 속성이 바인딩 DataList 의 디자인 ID(dlt_bind) 인지 확인합니다.\n[undefined] (미바인딩 확인) DataList 가 바인딩되지 않은 target2 의 getDataListInfo() 가 undefined 를 반환합니다.\n[Linked] (LinkedDataList 확인) target3.getDataListInfo().id 가 lnk_bind LinkedDataList 의 디자인 ID 인지 확인합니다."', '', 'label1');

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // GridView 와 바인딩할 DataList 동적 생성
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="dept" name="dept" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    let jsonData = [
        { "name": "John", "dept": "Sales" },
        { "name": "Jane", "dept": "Dev" },
        { "name": "Jack", "dept": "QA" }
    ];
    dlt_bind.setJSON(jsonData, false);

    // Property 설정은 createCList 공통 함수 사용 (dataList 바인딩)
    let properties = {
        dataList: "data:dlt_bind"
    };
    let cList = $c.gcm.createCList(properties);

    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:420px;height:200px;">';
    strTarget += '<w2:caption style="" id="caption1" value="dlt_bind 바인딩 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="200" style="" inputType="text" id="hcol1" value="이름"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol2" value="부서"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="200" style="" inputType="text" id="name" dataList="name"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="dept" dataList="dept"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate('target1', 'gridView', strTarget, grp_comp);

    // DataList 미바인딩 GridView (target2) — getDataListInfo() 가 undefined 반환하는 케이스 검증용
    let strTarget2 = '';
    strTarget2 += '<w2:gridView ' + strNameSpace + ' id="" style="width:420px;height:120px;">';
    strTarget2 += '<w2:caption style="" id="caption2" value="DataList 미바인딩 그리드 (target2)"></w2:caption>';
    strTarget2 += '<w2:header style="" id="header2">';
    strTarget2 += '<w2:row style="" id="hrow2">';
    strTarget2 += '<w2:column width="200" style="" inputType="text" id="hcol3" value="이름"></w2:column>';
    strTarget2 += '<w2:column width="*" style="" inputType="text" id="hcol4" value="부서"></w2:column>';
    strTarget2 += '</w2:row>';
    strTarget2 += '</w2:header>';
    strTarget2 += '<w2:gBody style="" id="gBody2">';
    strTarget2 += '<w2:row style="" id="brow2">';
    strTarget2 += '<w2:column width="200" style="" inputType="text" id="bcol3"></w2:column>';
    strTarget2 += '<w2:column width="*" style="" inputType="text" id="bcol4"></w2:column>';
    strTarget2 += '</w2:row>';
    strTarget2 += '</w2:gBody>';
    strTarget2 += '</w2:gridView>';

    scwin.target2 = await $p.dynamicCreate('target2', 'gridView', strTarget2, grp_comp);

    // LinkedDataList 바인딩 GridView (target3) — getDataListInfo().id 가 LinkedDataList 의 디자인 ID 반환하는 케이스 검증용.
    // LinkedDataList(lnk_bind) 는 dlt_bind DataList 를 bind 하여 생성하고, 그 LinkedDataList 를 GridView 의 dataList 로 연결한다.
    let strLinked = '';
    strLinked += '<w2:' + 'linkedDataList ' + strNameSpace + ' id="lnk_bind" bind="dlt_bind">';
    strLinked += '<w2:' + 'condition type="filter"></w2:' + 'condition>';
    strLinked += '<w2:' + 'condition type="sort"></w2:' + 'condition>';
    strLinked += '</w2:' + 'linkedDataList>';
    $p.data.create(strLinked);

    let strTarget3 = '';
    strTarget3 += '<w2:gridView ' + strNameSpace + ' id="" dataList="data:lnk_bind" style="width:420px;height:200px;">';
    strTarget3 += '<w2:caption style="" id="caption3" value="lnk_bind LinkedDataList 바인딩 그리드 (target3)"></w2:caption>';
    strTarget3 += '<w2:header style="" id="header3">';
    strTarget3 += '<w2:row style="" id="hrow3">';
    strTarget3 += '<w2:column width="200" style="" inputType="text" id="hcol5" value="이름"></w2:column>';
    strTarget3 += '<w2:column width="*" style="" inputType="text" id="hcol6" value="부서"></w2:column>';
    strTarget3 += '</w2:row>';
    strTarget3 += '</w2:header>';
    strTarget3 += '<w2:gBody style="" id="gBody3">';
    strTarget3 += '<w2:row style="" id="brow3">';
    strTarget3 += '<w2:column width="200" style="" inputType="text" id="name" dataList="name"></w2:column>';
    strTarget3 += '<w2:column width="*" style="" inputType="text" id="dept" dataList="dept"></w2:column>';
    strTarget3 += '</w2:row>';
    strTarget3 += '</w2:gBody>';
    strTarget3 += '</w2:gridView>';

    scwin.target3 = await $p.dynamicCreate('target3', 'gridView', strTarget3, grp_comp);
}



// 정보 확인 — 바인딩된 DataList 모듈의 정보 객체 반환.
// 반환 객체와 그 id 속성(디자인 ID)을 출력하여 검증
scwin.btn_getDataListInfo_onclick = function () {
    let result = target1.getDataListInfo();
    wf_body_bottom.getObj("scwin").setReturnValue("getDataListInfo() : " + JSON.stringify(result) + " / id : " + (result ? result.id : result));
}



// 미바인딩 확인 — DataList 가 바인딩되지 않은 target2 에서 호출.
// 바인딩된 DataList 가 없으면 getDataListInfo() 는 undefined 를 반환
scwin.btn_unbindDataListInfo_onclick = function () {
    let result = target2.getDataListInfo();
    wf_body_bottom.getObj("scwin").setReturnValue("[DataList 미바인딩 target2] getDataListInfo() : " + result);
}



// LinkedDataList 확인 — LinkedDataList 가 바인딩된 target3 에서 호출.
// LinkedDataList 모듈이 바인딩된 경우 getDataListInfo().id 는 LinkedDataList(lnk_bind) 의 디자인 ID 를 반환.
scwin.btn_getDataListInfoLinked_onclick = function () {
    let result = target3.getDataListInfo();
    wf_body_bottom.getObj("scwin").setReturnValue("[LinkedDataList 바인딩 target3] getDataListInfo() : " + JSON.stringify(result) + " / id : " + (result ? result.id : result));
}
